{
  inputs.nixpkgs.url = "github:NixOS/nixpkgs/master";

  outputs = { self, nixpkgs }: {
    packages = nixpkgs.lib.genAttrs [ "x86_64-linux" "aarch64-linux" "x86_64-darwin" "aarch64-darwin" ] (system:
      let
        pkgs = nixpkgs.legacyPackages.${system};
      in {
        default = pkgs.rustPlatform.buildRustPackage {
          pname = "rust-flake-example";
          version = "0.1.0";
          src = ./.;
          cargoLock.lockFile = ./Cargo.lock;
        };
      });
  };
}

{
  description = "jsonl2md";

  inputs = {
    nixpkgs.url = "github:NixOS/nixpkgs/89b910498aec952a955becb0c9d8edc6e813856f";
    flake-utils.url = "github:numtide/flake-utils";
  };

  outputs = { self, nixpkgs, flake-utils }:
    flake-utils.lib.eachDefaultSystem (system:
      let
        pkgs = import nixpkgs {
          inherit system;
          config.allowUnfree = true;
        };
      in
      {
        config.flake.description = "jsonl2md";

        packages.default = pkgs.rustPlatform.buildPackage {
          pname = "jsonl2md";
          version = "0.1.0";
          src = ./.;
          cargoBuildArgs = [ "--release" ];
        };

        devShells.default = pkgs.mkShell {
          buildInputs = [
            pkgs.rustPlatform.aarch64-linux
            pkgs.cargoBuild
          ];
        };
      });
}

